import{_ as l,a0 as h,w as k,s as e,I as t,x as i,a1 as n,A as p,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"向 Linus Torvalds 学习让编出的代码具有 “good taste” | LCTT x X-CMD","titleTemplate":false,"description":"向 Linus Torvalds 学习让编出的代码具有 “good taste” | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"向 Linus Torvalds 学习让编出的代码具有 “good taste” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"向 Linus Torvalds 学习让编出的代码具有 “good taste” | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20161026 Applying the Linus Torvalds Good Taste Coding Requirement","title":"向 Linus Torvalds 学习让编出的代码具有 “good taste”","tag":"201705","desc":""},"relativePath":"201705/20161026 Applying the Linus Torvalds Good Taste Coding Requirement.md","filePath":"[post].md"}'),r={name:"201705/20161026 Applying the Linus Torvalds Good Taste Coding Requirement.md"};function g(E,s,o,y,F,u){const a=h("Link");return k(),e("div",null,[s[16]||(s[16]=t("h1",{id:"向-linus-torvalds-学习让编出的代码具有-good-taste",tabindex:"-1"},[i("向 Linus Torvalds 学习让编出的代码具有 “good taste” "),t("a",{class:"header-anchor",href:"#向-linus-torvalds-学习让编出的代码具有-good-taste","aria-label":"Permalink to “向 Linus Torvalds 学习让编出的代码具有 “good taste””"},"​")],-1)),t("p",null,[s[1]||(s[1]=i("在",-1)),n(a,{href:"https://www.ted.com/talks/linus_torvalds_the_mind_behind_linux"},{default:p(()=>[...s[0]||(s[0]=[i("最近关于 Linus Torvalds 的一个采访中",-1)])]),_:1}),s[2]||(s[2]=i("，这位 Linux 的创始人，在采访过程中大约 14:20 的时候，提及了关于代码的 “good taste”。good taste？采访者请他展示更多的细节，于是，Linus Torvalds 展示了一张提前准备好的插图。",-1))]),s[17]||(s[17]=d(`<p>他展示的是一个代码片段。但这段代码并没有 “good taste”。这是一个具有 “poor taste” 的代码片段，把它作为例子，以提供一些初步的比较。</p><p><img src="https://d262ilb51hltx0.cloudfront.net/max/1200/1*X2VgEA_IkLvsCS-X4iPY7g.png" alt="Poor Taste Code Example"></p><p>这是一个用 C 写的函数，作用是删除链表中的一个对象，它包含有 10 行代码。</p><p>他把注意力集中在底部的 <code>if</code> 语句。正是这个 <code>if</code> 语句受到他的批判。</p><p>我暂停了这段视频，开始研究幻灯片。我发现我最近有写过和这很像的代码。Linus 不就是在说我的代码品味很差吗？我放下自傲，继续观看视频。</p><p>随后， Linus 向观众解释，正如我们所知道的，当从链表中删除一个对象时，需要考虑两种可能的情况。当所需删除的对象位于链表的表头时，删除过程和位于链表中间的情况不同。这就是这个 <code>if</code> 语句具有 “poor taste” 的原因。</p><p>但既然他承认考虑这两种不同的情况是必要的，那为什么像上面那样写如此糟糕呢？</p><p>接下来，他又向观众展示了第二张幻灯片。这个幻灯片展示的是实现同样功能的一个函数，但这段代码具有 “goog taste”　。</p><p><img src="https://d262ilb51hltx0.cloudfront.net/max/1200/1*GHFLYFB3vDQeakMyUGPglw.png" alt="Good Taste Code Example"></p><p>原先的 10 行代码现在减少为 4 行。</p><p>但代码的行数并不重要，关键是 <code>if</code> 语句，它不见了，因为不再需要了。代码已经被重构，所以，不用管对象在列表中的位置，都可以运用同样的操作把它删除。</p><p>Linus 解释了一下新的代码，它消除了边缘情况，就是这样。然后采访转入了下一个话题。</p><p>我琢磨了一会这段代码。 Linus 是对的，的确，第二个函数更好。如果这是一个确定代码具有 “good taste” 还是 “bad taste” 的测试，那么很遗憾，我失败了。我从未想到过有可能能够去除条件语句。我写过不止一次这样的 <code>if</code> 语句，因为我经常使用链表。</p><p>这个例子的意义，不仅仅是教给了我们一个从链表中删除对象的更好方法，而是启发了我们去思考自己写的代码。你通过程序实现的一个简单算法，可能还有改进的空间，只是你从来没有考虑过。</p><p>以这种方式，我回去审查最近正在做的项目的代码。也许是一个巧合，刚好也是用 C 写的。</p><p>我尽最大的能力去审查代码，“good taste” 的一个基本要求是关于边缘情况的消除方法，通常我们会使用条件语句来消除边缘情况。你的测试使用的条件语句越少，你的代码就会有更好的 “taste” 。</p><p>下面，我将分享一个通过审查代码进行了改进的一个特殊例子。</p><p>这是一个关于初始化网格边缘的算法。</p><p>下面所写的是一个用来初始化网格边缘的算法，网格 grid 以一个二维数组表示：grid[行][列] 。</p><p>再次说明，这段代码的目的只是用来初始化位于 grid 边缘的点的值，所以，只需要给最上方一行、最下方一行、最左边一列以及最右边一列赋值即可。</p><p>为了完成这件事，我通过循环遍历 grid 中的每一个点，然后使用条件语句来测试该点是否位于边缘。代码看起来就是下面这样：</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRID_SIZE; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRID_SIZE; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // Top Edge</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[r][c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // Left Edge</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[r][c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // Right Edge</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRID_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[r][c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // Bottom Edge</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRID_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[r][c] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>虽然这样做是对的，但回过头来看，这个结构存在一些问题。</p><ol><li>复杂性 — 在双层循环里面使用 4 个条件语句似乎过于复杂。</li><li>高效性 — 假设 <code>GRID_SIZE</code> 的值为 64，那么这个循环需要执行 4096 次，但需要进行赋值的只有位于边缘的 256 个点。</li></ol><p>用 Linus 的眼光来看，将会认为这段代码没有 “good taste” 。</p><p>所以，我对上面的问题进行了一下思考。经过一番思考，我把复杂度减少为包含四个条件语句的单层 <code>for</code> 循环。虽然只是稍微改进了一下复杂性，但在性能上也有了极大的提高，因为它只是沿着边缘的点进行了 256 次循环。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for (i = 0; i &lt; GRID_SIZE * 4; ++i) {</span></span>
<span class="line"><span>    // Top Edge</span></span>
<span class="line"><span>    if (i &lt; GRID_SIZE)</span></span>
<span class="line"><span>        grid[0][i] = 0;</span></span>
<span class="line"><span>    // Right Edge</span></span>
<span class="line"><span>    else if (i &lt; GRID_SIZE * 2)</span></span>
<span class="line"><span>        grid[i - GRID_SIZE][GRID_SIZE - 1] = 0;</span></span>
<span class="line"><span>    // Left Edge</span></span>
<span class="line"><span>    else if (i &lt; GRID_SIZE * 3)</span></span>
<span class="line"><span>        grid[i - (GRID_SIZE * 2)][0] = 0;</span></span>
<span class="line"><span>    // Bottom Edge</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        grid[GRID_SIZE - 1][i - (GRID_SIZE * 3)] = 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>的确是一个很大的提高。但是它看起来很丑，并不是易于阅读理解的代码。基于这一点，我并不满意。</p><p>我继续思考，是否可以进一步改进呢？事实上，答案是 YES！最后，我想出了一个非常简单且优雅的算法，老实说，我不敢相信我会花了那么长时间才发现这个算法。</p><p>下面是这段代码的最后版本。它只有一层 <code>for</code> 循环并且没有条件语句。另外。循环只执行了 64 次迭代，极大的改善了复杂性和高效性。</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GRID_SIZE; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Top Edge</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Bottom Edge</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[GRID_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Left Edge</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i][</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Right Edge</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i][GRID_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这段代码通过每次循环迭代来初始化四条边缘上的点。它并不复杂，而且非常高效，易于阅读。和原始的版本，甚至是第二个版本相比，都有天壤之别。</p><p>至此，我已经非常满意了。</p><p>那么，我是一个有 “good taste” 的开发者么？</p><p>我觉得我是，但是这并不是因为我上面提供的这个例子，也不是因为我在这篇文章中没有提到的其它代码……而是因为具有 “good taste” 的编码工作远非一段代码所能代表。Linus 自己也说他所提供的这段代码不足以表达他的观点。</p><p>我明白 Linus 的意思，也明白那些具有 “good taste” 的程序员虽各有不同，但是他们都是会将他们之前开发的代码花费时间重构的人。他们明确界定了所开发的组件的边界，以及是如何与其它组件之间的交互。他们试着确保每一样工作都完美、优雅。</p><p>其结果就是类似于 Linus 的 “good taste” 的例子，或者像我的例子一样，不过是千千万万个 “good taste”。</p><p>你会让你的下个项目也具有这种 “good taste” 吗？</p><hr>`,39)),t("p",null,[s[4]||(s[4]=i("via: ",-1)),n(a,{href:"https://medium.com/@bartobri/applying-the-linus-tarvolds-good-taste-coding-requirement-99749f37684a"},{default:p(()=>[...s[3]||(s[3]=[i("https://medium.com/@bartobri/applying-the-linus-tarvolds-good-taste-coding-requirement-99749f37684a",-1)])]),_:1})]),t("p",null,[s[8]||(s[8]=i("作者：",-1)),n(a,{href:"https://medium.com/@bartobri?source=post_header_lockup"},{default:p(()=>[...s[5]||(s[5]=[i("Brian Barto",-1)])]),_:1}),s[9]||(s[9]=i(" 译者：",-1)),n(a,{href:"https://github.com/ucasFL"},{default:p(()=>[...s[6]||(s[6]=[i("ucasFL",-1)])]),_:1}),s[10]||(s[10]=i(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[i("LCTT",-1)])]),_:1}),s[14]||(s[14]=i(" 组织编译，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[i("Linux中国",-1)])]),_:1}),s[15]||(s[15]=i(" 荣誉推出",-1))])])}const A=l(r,[["render",g]]);export{c as __pageData,A as default};
